function firstElementSafe(arr) {
  if (arr.length === 0) return { tag: 'None' };
  return { tag: 'Some', value: arr[0].toUpperCase() };
}

function describe(opt) {
  return opt.tag === 'Some' ? `拿到：${opt.value}` : '陣列是空的';
}

console.log(describe(firstElementSafe(['hello', 'world'])));
console.log(describe(firstElementSafe([])));

